// NULL-tolerant scan buffer for settlementRunScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type settlementRunPreloadBuf struct {
	ID          sql.Null[uuid.UUID]
	HouseholdID sql.Null[uuid.UUID]
	Period      sql.Null[string]
	Revision    sql.Null[int64]
	Status      sql.Null[string]
	CreatedBy   sql.Null[uuid.UUID]
	CreatedAt   sql.Null[time.Time]
}

// settlementRunScanMapperNullable maps the preloaded settlementRun
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func settlementRunScanMapperNullable(prefix string) scan.Mapper[*SettlementRun] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*SettlementRun, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *settlementRunPreloadBuf) any
		}
		targets := make([]target, 0, 7)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *settlementRunPreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *settlementRunPreloadBuf) any { return &b.HouseholdID }})
			case "period":
				targets = append(targets, target{i, func(b *settlementRunPreloadBuf) any { return &b.Period }})
			case "revision":
				targets = append(targets, target{i, func(b *settlementRunPreloadBuf) any { return &b.Revision }})
			case "status":
				targets = append(targets, target{i, func(b *settlementRunPreloadBuf) any { return &b.Status }})
			case "created_by":
				targets = append(targets, target{i, func(b *settlementRunPreloadBuf) any { return &b.CreatedBy }})
			case "created_at":
				targets = append(targets, target{i, func(b *settlementRunPreloadBuf) any { return &b.CreatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(settlementRunPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*SettlementRun, error) {
				buf := link.(*settlementRunPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.Period.Valid) &&
					!(buf.Revision.Valid) &&
					!(buf.Status.Valid) &&
					!(buf.CreatedBy.Valid) &&
					!(buf.CreatedAt.Valid) {
					return nil, nil
				}

				o := new(SettlementRun)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				if buf.Period.Valid {
					o.Period = buf.Period.V
				}
				if buf.Revision.Valid {
					o.Revision = buf.Revision.V
				}
				if buf.Status.Valid {
					o.Status = buf.Status.V
				}
				if buf.CreatedBy.Valid {
					o.CreatedBy = buf.CreatedBy.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				return o, nil
			}
	}
}

func (o *SettlementRun) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "SettlementLines":
		rels, ok := retrieved.(SettlementLineSlice)
		if !ok {
			return fmt.Errorf("settlementRun cannot load %T as %q", retrieved, name)
		}

		o.R.SettlementLines = rels
		o.R.Loaded.SettlementLines = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.SettlementRun = o
				rel.R.Loaded.SettlementRun = true
			}
		}
		return nil
	case "CreatedByMember":
		rel, ok := retrieved.(*Member)
		if !ok {
			return fmt.Errorf("settlementRun cannot load %T as %q", retrieved, name)
		}

		o.R.CreatedByMember = rel
		o.R.Loaded.CreatedByMember = true

		if rel != nil {
			rel.R.CreatedBySettlementRuns = SettlementRunSlice{o}
		}
		return nil
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("settlementRun cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.SettlementRuns = SettlementRunSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("settlementRun has no relationship %q", name)
	}
}

type settlementRunPreloader struct {
	CreatedByMember func(...psql.PreloadOption) psql.Preloader
	Household       func(...psql.PreloadOption) psql.Preloader
}

func buildSettlementRunPreloader() settlementRunPreloader {
	return settlementRunPreloader{
		CreatedByMember: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Member, MemberSlice](psql.PreloadRel{
				Name: "CreatedByMember",
				Sides: []psql.PreloadSide{
					{
						From:        SettlementRuns,
						To:          Members,
						FromColumns: []string{"created_by"},
						ToColumns:   []string{"id"},
					},
				},
			}, Members.Columns.Names(), memberScanMapperNullable, opts...)
		},
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        SettlementRuns,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
	}
}

