// LoadSettlementLines loads the settlementRun's SettlementLines into the .R struct
func (o *SettlementRun) LoadSettlementLines(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.SettlementLines = nil
	o.R.Loaded.SettlementLines = false

	related, err := o.SettlementLines(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.SettlementRun = o
		rel.R.Loaded.SettlementRun = true
	}

	o.R.SettlementLines = related
	o.R.Loaded.SettlementLines = true
	return nil
}

// LoadSettlementLines loads the settlementRun's SettlementLines into the .R struct
func (os SettlementRunSlice) LoadSettlementLines(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	settlementLines, err := os.SettlementLines(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.SettlementLines = nil
		o.R.Loaded.SettlementLines = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	settlementRunByKey := make(map[uuid.UUID][]*SettlementRun, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		settlementRunByKey[o.ID] = append(settlementRunByKey[o.ID], o)
	}

	for _, rel := range settlementLines {

		owners, ok := settlementRunByKey[rel.SettlementRunID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.SettlementRun = o
			rel.R.Loaded.SettlementRun = true

			o.R.SettlementLines = append(o.R.SettlementLines, rel)

		}
	}

	return nil
}

// LoadCreatedByMember loads the settlementRun's CreatedByMember into the .R struct
func (o *SettlementRun) LoadCreatedByMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.CreatedByMember = nil
	o.R.Loaded.CreatedByMember = false

	related, err := o.CreatedByMember(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.CreatedBySettlementRuns = SettlementRunSlice{o}

	o.R.CreatedByMember = related
	o.R.Loaded.CreatedByMember = true
	return nil
}

// LoadCreatedByMember loads the settlementRun's CreatedByMember into the .R struct
func (os SettlementRunSlice) LoadCreatedByMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	members, err := os.CreatedByMember(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.CreatedByMember = nil
		o.R.Loaded.CreatedByMember = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	settlementRunByKey := make(map[uuid.UUID][]*SettlementRun, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		settlementRunByKey[o.CreatedBy] = append(settlementRunByKey[o.CreatedBy], o)
	}

	for _, rel := range members {

		owners, ok := settlementRunByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.CreatedByMember != nil {
				continue
			}

			rel.R.CreatedBySettlementRuns = append(rel.R.CreatedBySettlementRuns, o)

			o.R.CreatedByMember = rel

		}
	}

	return nil
}

// LoadHousehold loads the settlementRun's Household into the .R struct
func (o *SettlementRun) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Household = nil
	o.R.Loaded.Household = false

	related, err := o.Household(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.SettlementRuns = SettlementRunSlice{o}

	o.R.Household = related
	o.R.Loaded.Household = true
	return nil
}

// LoadHousehold loads the settlementRun's Household into the .R struct
func (os SettlementRunSlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	settlementRunByKey := make(map[uuid.UUID][]*SettlementRun, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		settlementRunByKey[o.HouseholdID] = append(settlementRunByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := settlementRunByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.SettlementRuns = append(rel.R.SettlementRuns, o)

			o.R.Household = rel

		}
	}

	return nil
}

// settlementRunC is where relationship counts are stored.
type settlementRunC struct {
	SettlementLines *int64
}

// PreloadCount sets a count in the C struct by name
func (o *SettlementRun) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "SettlementLines":
		o.C.SettlementLines = &count
	}
	return nil
}

type settlementRunCountPreloader struct {
	SettlementLines func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildSettlementRunCountPreloader() settlementRunCountPreloader {
	return settlementRunCountPreloader{
		SettlementLines: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*SettlementRun]("SettlementLines", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = SettlementRuns.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(SettlementLines.NameAsExpr()),
					sm.Where(psql.Quote(SettlementLines.Alias(), "settlement_run_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

type settlementRunCountThenLoader[Q orm.Loadable] struct {
	SettlementLines func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildSettlementRunCountThenLoader[Q orm.Loadable]() settlementRunCountThenLoader[Q] {
	type SettlementLinesCountInterface interface {
		LoadCountSettlementLines(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return settlementRunCountThenLoader[Q]{
		SettlementLines: countThenLoadBuilder[Q](
			"SettlementLines",
			func(ctx context.Context, exec bob.Executor, retrieved SettlementLinesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountSettlementLines(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountSettlementLines loads the count of SettlementLines into the C struct
func (o *SettlementRun) LoadCountSettlementLines(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.SettlementLines(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.SettlementLines = &count
	return nil
}

// LoadCountSettlementLines loads the count of SettlementLines for a slice in a single batch query
func (os SettlementRunSlice) LoadCountSettlementLines(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[uuid.UUID], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "uuid[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    uuid.UUID
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			SettlementLines.Columns.SettlementRunID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(SettlementLines.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(SettlementLines.Columns.SettlementRunID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(SettlementLines.Columns.SettlementRunID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[uuid.UUID]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.SettlementLines = &count
	}

	return nil
}

type settlementRunJoins[Q dialect.Joinable] struct {
	typ             string
	SettlementLines modAs[Q, settlementLineColumns]
	CreatedByMember modAs[Q, memberColumns]
	Household       modAs[Q, householdColumns]
}

func (j settlementRunJoins[Q]) aliasedAs(alias string) settlementRunJoins[Q] {
	return buildSettlementRunJoins[Q](buildSettlementRunColumns(alias), j.typ)
}

func buildSettlementRunJoins[Q dialect.Joinable](cols settlementRunColumns, typ string) settlementRunJoins[Q] {
	return settlementRunJoins[Q]{
		typ: typ,
		SettlementLines: modAs[Q, settlementLineColumns]{
			c: SettlementLines.Columns,
			f: func(to settlementLineColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, SettlementLines.NameExpr().As(to.Alias())).On(
						to.SettlementRunID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		CreatedByMember: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.CreatedBy),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
	}
}
